// Generates lib/core/theme/tokens.g.dart from the Claude Design export design/system/tokens.json.
//
//   design/system/tokens.json   (design source — do not edit by hand, re-export from Claude Design)
//        ↓  dart run tool/gen_tokens.dart
//   lib/core/theme/tokens.g.dart (GENERATED — do not edit)
//
// Output:
//   * AppColors    ThemeExtension — every colour token, light + dark (aliases like `{brand}` resolved)
//   * AppElevation ThemeExtension — shadow tokens (CSS box-shadow → BoxShadow), light + dark
//   * AppType      TextStyle per type token (family, size, line height, weight, letter spacing)
//   * AppSpace / AppRadius / AppSize   numeric tokens
//
// Usage:
//   dart run tool/gen_tokens.dart          write the Dart file
//   dart run tool/gen_tokens.dart --check  exit 1 if the Dart file is out of date (CI)
//   dart run tool/gen_tokens.dart --in path/tokens.json --out path/tokens.g.dart
//
// Studio note: nothing here is Subnest-specific except the default paths and the font family
// name, so the script can be copied to the next app that gets a Claude Design export.
import 'dart:convert';
import 'dart:io';

const defaultIn = 'design/system/tokens.json';
const defaultOut = 'lib/core/theme/tokens.g.dart';

/// Family name declared in pubspec.yaml `flutter: fonts:` (the bundled TTFs).
const fontFamily = 'BeVietnamPro';

void main(List<String> args) {
  String arg(String name, String fallback) {
    final i = args.indexOf(name);
    return i >= 0 && i + 1 < args.length ? args[i + 1] : fallback;
  }

  final inPath = arg('--in', defaultIn);
  final outPath = arg('--out', defaultOut);
  final json = jsonDecode(File(inPath).readAsStringSync()) as Map<String, Object?>;
  final code = generate(json, source: inPath);
  final out = File(outPath);
  if (args.contains('--check')) {
    // Format a scratch copy inside the project (so analysis_options.yaml page width applies) and compare.
    final tmp = File('.dart_tool/gen_tokens_check.dart')..createSync(recursive: true);
    tmp.writeAsStringSync(code);
    _format(tmp.path);
    final fresh = tmp.readAsStringSync();
    tmp.deleteSync();
    if (!out.existsSync() || out.readAsStringSync() != fresh) {
      stderr.writeln('$outPath is out of date — run: dart run tool/gen_tokens.dart');
      exit(1);
    }
    stdout.writeln('$outPath is up to date.');
    return;
  }
  out.writeAsStringSync(code);
  _format(outPath);
  stdout.writeln('Wrote $outPath');
}

void _format(String path) {
  final r = Process.runSync('dart', ['format', path], runInShell: true);
  if (r.exitCode != 0) {
    stderr.writeln(r.stderr);
    exit(1);
  }
}

// ---------------------------------------------------------------------------------------------

String generate(Map<String, Object?> json, {required String source}) {
  final b = StringBuffer()
    ..writeln('// GENERATED by tool/gen_tokens.dart from $source — do not edit by hand.')
    ..writeln('// Re-run `dart run tool/gen_tokens.dart` after a new Claude Design export.')
    ..writeln('// ignore_for_file: public_member_api_docs, lines_longer_than_80_chars')
    ..writeln()
    ..writeln("import 'package:flutter/material.dart';")
    ..writeln();
  _colors(b, json['color'] as Map<String, Object?>);
  _shadows(b, json['shadow'] as Map<String, Object?>);
  _type(b, json['type'] as Map<String, Object?>);
  _numbers(b, 'AppSpace', 'Spacing (4/8 grid).', json['spacing'] as Map<String, Object?>, 'space-');
  _numbers(b, 'AppRadius', 'Corner radii.', json['radius'] as Map<String, Object?>, 'radius-');
  _numbers(b, 'AppSize', 'Touch targets and fixed component heights.', json['size'] as Map<String, Object?>, '');
  return b.toString();
}

// ---- colours ---------------------------------------------------------------------------------

class _ColorToken {
  _ColorToken(this.name, this.light, this.dark, this.usage);
  final String name;
  String light;
  String dark;
  final String usage;
  String get field => _camel(name);
}

void _colors(StringBuffer b, Map<String, Object?> color) {
  final tokens = <_ColorToken>[];
  for (final raw in (color['tokens'] as List).cast<Map<String, Object?>>()) {
    final v = raw['value'];
    final (light, dark) = v is Map ? (v['light'] as String, v['dark'] as String) : (v as String, v);
    tokens.add(_ColorToken(raw['name'] as String, light, dark, (raw['usage'] as String?) ?? ''));
  }
  // Resolve `{alias}` references.
  final byName = {for (final t in tokens) t.name: t};
  String resolve(String v, bool dark, [int depth = 0]) {
    final m = RegExp(r'^\{(.+)\}$').firstMatch(v.trim());
    if (m == null) return v;
    if (depth > 5) throw StateError('alias loop at $v');
    final target = byName[m.group(1)] ?? (throw StateError('unknown alias $v'));
    return resolve(dark ? target.dark : target.light, dark, depth + 1);
  }

  for (final t in tokens) {
    t.light = resolve(t.light, false);
    t.dark = resolve(t.dark, true);
  }

  b
    ..writeln('/// Colour tokens (design/system/README.md § Colour). Read with `context.colors.<token>`.')
    ..writeln('@immutable')
    ..writeln('class AppColors extends ThemeExtension<AppColors> {')
    ..writeln('  const AppColors({')
    ..writeAll(tokens.map((t) => '    required this.${t.field},\n'))
    ..writeln('  });')
    ..writeln();
  for (final t in tokens) {
    b
      ..writeln('  /// `${t.name}` — ${t.usage}')
      ..writeln('  final Color ${t.field};')
      ..writeln();
  }
  for (final (name, dark) in [('light', false), ('dark', true)]) {
    b.writeln('  static const $name = AppColors(');
    for (final t in tokens) {
      b.writeln('    ${t.field}: ${_color(dark ? t.dark : t.light)},');
    }
    b
      ..writeln('  );')
      ..writeln();
  }
  final tiles = tokens.where((t) => t.name.startsWith('tile-') && t.name != 'tile-ring').toList();
  b
    ..writeln('  /// Custom-service tile palette in design order (same in every theme).')
    ..writeln('  static const tilePalette = <Color>[')
    ..writeAll(tiles.map((t) => '    ${_color(t.light)}, // ${t.name}\n'))
    ..writeln('  ];')
    ..writeln()
    ..writeln('  /// Every token by its design name (gallery, debugging).')
    ..writeln('  Map<String, Color> get byName => {')
    ..writeAll(tokens.map((t) => "    '${t.name}': ${t.field},\n"))
    ..writeln('  };')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  AppColors copyWith({')
    ..writeAll(tokens.map((t) => '    Color? ${t.field},\n'))
    ..writeln('  }) => AppColors(')
    ..writeAll(tokens.map((t) => '    ${t.field}: ${t.field} ?? this.${t.field},\n'))
    ..writeln('  );')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  AppColors lerp(covariant ThemeExtension<AppColors>? other, double t) {')
    ..writeln('    if (other is! AppColors) return this;')
    ..writeln('    return AppColors(')
    ..writeAll(tokens.map((t) => '      ${t.field}: Color.lerp(${t.field}, other.${t.field}, t)!,\n'))
    ..writeln('    );')
    ..writeln('  }')
    ..writeln('}')
    ..writeln();
}

/// `#rrggbb` / `#rrggbbaa` / `#rgb` → `Color(0xAARRGGBB)`.
String _color(String css) {
  var h = css.trim().replaceFirst('#', '');
  if (h.length == 3) h = h.split('').map((c) => '$c$c').join();
  final rgb = h.substring(0, 6);
  final a = h.length == 8 ? h.substring(6, 8) : 'ff';
  return 'Color(0x${(a + rgb).toUpperCase()})';
}

// ---- shadows ---------------------------------------------------------------------------------

void _shadows(StringBuffer b, Map<String, Object?> shadow) {
  final tokens = (shadow['tokens'] as List).cast<Map<String, Object?>>();
  final fields = tokens.map((t) => _camel((t['name'] as String).replaceFirst('shadow-', ''))).toList();
  b
    ..writeln('/// Shadow tokens. Light: soft shadows. Dark: no card shadow — `card` is a 1px `line` ring.')
    ..writeln('/// Read with `context.elevation.card` / `.float`.')
    ..writeln('@immutable')
    ..writeln('class AppElevation extends ThemeExtension<AppElevation> {')
    ..writeln('  const AppElevation({${fields.map((f) => 'required this.$f').join(', ')}});')
    ..writeln();
  for (var i = 0; i < tokens.length; i++) {
    b
      ..writeln('  /// `${tokens[i]['name']}` — ${tokens[i]['usage']}')
      ..writeln('  final List<BoxShadow> ${fields[i]};')
      ..writeln();
  }
  for (final mode in ['light', 'dark']) {
    b.writeln('  static const $mode = AppElevation(');
    for (var i = 0; i < tokens.length; i++) {
      final v = tokens[i]['value'];
      final css = v is Map ? v[mode] as String : v as String;
      b.writeln('    ${fields[i]}: [${_boxShadows(css).join(', ')}],');
    }
    b
      ..writeln('  );')
      ..writeln();
  }
  b
    ..writeln('  @override')
    ..writeln('  AppElevation copyWith({${fields.map((f) => 'List<BoxShadow>? $f').join(', ')}}) =>')
    ..writeln('      AppElevation(${fields.map((f) => '$f: $f ?? this.$f').join(', ')});')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  AppElevation lerp(covariant ThemeExtension<AppElevation>? other, double t) =>')
    ..writeln('      other is AppElevation && t >= 0.5 ? other : this;')
    ..writeln('}')
    ..writeln();
}

List<String> _boxShadows(String css) {
  final out = <String>[];
  for (final part in css.split(RegExp(r',\s*(?=-?\d)'))) {
    final bits = part.trim().split(RegExp(r'\s+'));
    final color = bits.firstWhere((x) => x.startsWith('#'));
    final nums = bits.where((x) => !x.startsWith('#')).map((x) => double.parse(x.replaceAll('px', ''))).toList();
    final dx = nums[0], dy = nums[1];
    final blur = nums.length > 2 ? nums[2] : 0.0;
    final spread = nums.length > 3 ? nums[3] : 0.0;
    out.add(
      'BoxShadow(color: ${_color(color)}, offset: Offset(${_n(dx)}, ${_n(dy)}), '
      'blurRadius: ${_n(blur)}, spreadRadius: ${_n(spread)})',
    );
  }
  return out;
}

// ---- type ------------------------------------------------------------------------------------

void _type(StringBuffer b, Map<String, Object?> type) {
  b
    ..writeln('/// Type scale on Be Vietnam Pro (no colour — text inherits `ink` from the theme).')
    ..writeln('/// Money: add `.tabular` (see app_theme.dart) — the bundled TTFs carry a `tnum` feature.')
    ..writeln('abstract final class AppType {')
    ..writeln("  static const fontFamily = '$fontFamily';")
    ..writeln();
  for (final g in (type['groups'] as List).cast<Map<String, Object?>>()) {
    for (final s in (g['styles'] as List).cast<Map<String, Object?>>()) {
      final size = _px(s['fontSize']);
      final lh = _px(s['lineHeight']);
      final ls = (s['letterSpacing'] as String?) ?? '0';
      final em = ls.endsWith('em') ? double.parse(ls.replaceAll('em', '')) : 0.0;
      final px = ls.endsWith('px') ? double.parse(ls.replaceAll('px', '')) : em * size;
      b
        ..writeln('  /// `${s['name']}` ${_n(size)}/${_n(lh)} w${s['fontWeight']} — ${s['usage']}')
        ..writeln('  static const ${_camel(s['name'] as String)} = TextStyle(')
        ..writeln('    fontFamily: fontFamily,')
        ..writeln('    fontSize: ${_n(size)},')
        ..writeln('    height: ${_n(lh)} / ${_n(size)},')
        ..writeln('    fontWeight: FontWeight.w${s['fontWeight']},')
        ..writeln('    letterSpacing: ${_n(_round(px))},')
        ..writeln('  );')
        ..writeln();
    }
  }
  b
    ..writeln('}')
    ..writeln();
}

// ---- numbers ---------------------------------------------------------------------------------

void _numbers(StringBuffer b, String cls, String doc, Map<String, Object?> group, String prefix) {
  b
    ..writeln('/// ${(group['note'] as String?) ?? doc}')
    ..writeln('abstract final class $cls {');
  for (final t in (group['tokens'] as List).cast<Map<String, Object?>>()) {
    final name = (t['name'] as String).replaceFirst(prefix, '');
    var field = _camel(name);
    if (RegExp(r'^\d').hasMatch(field)) field = 's$field';
    b
      ..writeln('  /// `${t['name']}` — ${t['usage']}')
      ..writeln('  static const double $field = ${_n(_px(t['value']))};');
  }
  b
    ..writeln('}')
    ..writeln();
}

// ---- helpers ---------------------------------------------------------------------------------

double _px(Object? v) => v is num ? v.toDouble() : double.parse((v as String).replaceAll('px', '').trim());

double _round(double v) => (v * 1000).roundToDouble() / 1000;

String _n(double v) => v == v.roundToDouble() ? v.toStringAsFixed(0) : '$v';

/// `surface-2` → `surface2`, `on-brand-soft` → `onBrandSoft`, `tile-24` → `tile24`.
String _camel(String s) {
  final parts = s.split('-');
  return parts.first + parts.skip(1).map((p) => p.isEmpty ? '' : p[0].toUpperCase() + p.substring(1)).join();
}
